interface OrderPort { suspend fun place(order: Order): Receipt }

class LegacyOrderAdapter(private val client: LegacyClient) : OrderPort {
    override suspend fun place(order: Order): Receipt =
        when (val r = client.submit(order.toLegacy())) {     // translate + call
            is LegacyResult.Ok -> r.payload.toReceipt()      // local type out
            is LegacyResult.Rejected -> throw OrderRejected(r.reason)
        }
}

fun Order.toLegacy() = LegacyOrderDto(orderId = id.value, qty = quantity)
